-- =====================================================================
-- Seed real do módulo de Fretes — importado de frete.js (protótipo
-- "Cotação de Frete" já usado hoje). Cada bloco é uma Transportadora+UF;
-- valor_por_nf/taxa_coleta <= 1 no arquivo original = percentual, > 1 =
-- valor fixo em R$ (ex.: Potyguar cobra R$ 11,00 fixos de NF). Idempotente
-- (pode rodar de novo sem duplicar) via ON CONFLICT (nome, uf) /
-- (transportadora_id, cidade).
-- =====================================================================

-- ---- Cbirdex — CE (181 cidades) ----
do $$
declare
  v_id uuid;
begin
  values ('Cbirdex', 'CE', 0.45, 0.005, 'percentual', 0, 'percentual', 60, 24, null, 0)
  on conflict (nome, uf) do update set
    valor_por_kg = excluded.valor_por_kg, valor_por_nf = excluded.valor_por_nf, valor_por_nf_tipo = excluded.valor_por_nf_tipo,
    taxa_coleta = excluded.taxa_coleta, taxa_coleta_tipo = excluded.taxa_coleta_tipo, frete_minimo = excluded.frete_minimo,
    prazo_padrao_horas = excluded.prazo_padrao_horas, prazo_padrao_texto = excluded.prazo_padrao_texto
  returning id into v_id;

end $$;

